-- ES/DE/FR translations for the rest of Romania's deep-dive content.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Control Continuo de Transacciones (CTC)', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Las reglas de validación RO_CIUS, los puntos de acceso de la API y los importes de las sanciones cambian — confirme las especificaciones actuales directamente en el portal e-Factura de la ANAF antes de construir una integración.', 'Rumanía implementó RO e-Factura por etapas — comenzando como un canal voluntario y volviéndose obligatorio, tipo de transacción por tipo de transacción. Esta es la secuencia completa, pasada y futura.', 'Toda factura es un archivo XML estructurado — no existe un equivalente en PDF o papel con validez legal una vez que está dentro del alcance.', 'Rumanía opera un modelo de compensación centralizado (CTC): nada es legalmente una factura hasta que la ANAF la ha validado y sellado.', 'Antes de poder enviar o recibir una sola factura, existe un proceso de configuración único con la autoridad fiscal central.', 'E-Factura no existe de forma aislada — dos regímenes de reporte rumanos adyacentes suelen confundir a los recién llegados.' FROM countries WHERE name_en = 'Romania';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Kontinuierliche Transaktionskontrolle (CTC)', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. RO_CIUS-Validierungsregeln, API-Endpunkte und Bußgeldbeträge ändern sich — bestätigen Sie aktuelle Spezifikationen direkt auf dem e-Factura-Portal der ANAF, bevor Sie eine Integration aufbauen.', 'Rumänien führte RO e-Factura in Stufen ein — zunächst als freiwilliger Kanal, dann Transaktionstyp für Transaktionstyp verpflichtend werdend. Dies ist die vollständige Abfolge, vergangen und bevorstehend.', 'Jede Rechnung ist eine strukturierte XML-Datei — sobald Sie im Anwendungsbereich sind, gibt es kein PDF- oder Papier-Äquivalent mit Rechtswirkung.', 'Rumänien betreibt ein zentralisiertes Clearing-Modell (CTC): Nichts gilt rechtlich als Rechnung, bevor die ANAF sie validiert und versiegelt hat.', 'Bevor Sie auch nur eine einzige Rechnung senden oder empfangen können, ist ein einmaliger Einrichtungsprozess bei der zentralen Steuerbehörde erforderlich.', 'E-Factura steht nicht für sich allein — zwei angrenzende rumänische Meldesysteme bringen Neueinsteiger häufig ins Stolpern.' FROM countries WHERE name_en = 'Romania';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle continu des transactions (CTC)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les règles de validation RO_CIUS, les points d''accès API et les montants des sanctions évoluent — confirmez les spécifications actuelles directement sur le portail e-Factura de l''ANAF avant de construire une intégration.', 'La Roumanie a déployé RO e-Factura par étapes — d''abord comme canal volontaire, puis devenant obligatoire type de transaction par type de transaction. Voici la séquence complète, passée et à venir.', 'Chaque facture est un fichier XML structuré — il n''existe aucun équivalent PDF ou papier ayant une valeur légale dès lors que vous entrez dans le champ d''application.', 'La Roumanie applique un modèle de contrôle centralisé (CTC) : rien n''est légalement une facture tant que l''ANAF ne l''a pas validée et scellée.', 'Avant de pouvoir envoyer ou recevoir la moindre facture, une procédure de configuration unique doit être effectuée auprès de l''administration fiscale centrale.', 'E-Factura ne fonctionne pas isolément — deux régimes de déclaration roumains voisins déstabilisent souvent les nouveaux venus.' FROM countries WHERE name_en = 'Romania';

