INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Sintaxis y estándar', '[["Sintaxis base", "UBL 2.1 (ISO/IEC 19845)"], ["Modelo semántico europeo", "EN 16931"], ["Extensión nacional (CIUS)", "RO_CIUS 1.0.1"], ["Base legal de la CIUS", "Orden del MF 1366/2021"]]', 'El XML CII está técnicamente permitido por el estándar EN 16931, pero en la práctica la plataforma de la ANAF valida realmente UBL 2.1 — use UBL a menos que tenga una razón específica para no hacerlo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Syntax & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Syntax & Standard', '[["Basissyntax", "UBL 2.1 (ISO/IEC 19845)"], ["Europäisches Semantikmodell", "EN 16931"], ["Nationale Erweiterung (CIUS)", "RO_CIUS 1.0.1"], ["Rechtsgrundlage der CIUS", "Anordnung des Finanzministeriums 1366/2021"]]', 'CII-XML ist gemäß dem EN-16931-Standard technisch zulässig, aber in der Praxis validiert die ANAF-Plattform tatsächlich UBL 2.1 — verwenden Sie UBL, sofern Sie keinen bestimmten Grund dagegen haben.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Syntax & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Syntaxe et norme', '[["Syntaxe de base", "UBL 2.1 (ISO/IEC 19845)"], ["Modèle sémantique européen", "EN 16931"], ["Extension nationale (CIUS)", "RO_CIUS 1.0.1"], ["Base légale de la CIUS", "Arrêté du ministère des Finances 1366/2021"]]', 'Le XML CII est techniquement autorisé par la norme EN 16931, mais c''est UBL 2.1 que la plateforme de l''ANAF valide réellement en pratique — utilisez UBL sauf raison spécifique de ne pas le faire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Syntax & standard';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Canal de validación', '[["Paso 1", "Validación estructural XSD"], ["Paso 2", "Reglas de negocio Schematron"], ["Número de reglas", "~118 reglas RO_CIUS"], ["Verificación del NIF", "Consulta en tiempo real de CUI/CIF"]]', 'Los NIF CUI/CIF no válidos o inactivos provocan un rechazo inmediato — el sistema cruza la información con la base de datos de contribuyentes en vivo de la ANAF como parte de la validación, no solo una comprobación de formato.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Validation pipeline';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Validierungspipeline', '[["Schritt 1", "Strukturelle XSD-Validierung"], ["Schritt 2", "Schematron-Geschäftsregeln"], ["Regelanzahl", "~118 RO_CIUS-Regeln"], ["Steuer-ID-Prüfung", "Echtzeit-Abfrage von CUI/CIF"]]', 'Ungültige oder inaktive CUI/CIF-Steuer-IDs führen zur sofortigen Ablehnung — das System gleicht als Teil der Validierung mit der Live-Steuerpflichtigendatenbank der ANAF ab, nicht nur mit einer Formatprüfung.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Validation pipeline';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Pipeline de validation', '[["Étape 1", "Validation structurelle XSD"], ["Étape 2", "Règles métier Schematron"], ["Nombre de règles", "~118 règles RO_CIUS"], ["Vérification du numéro fiscal", "Consultation en temps réel du CUI/CIF"]]', 'Des numéros fiscaux CUI/CIF invalides ou inactifs entraînent un rejet immédiat — le système croise les données avec la base des contribuables en temps réel de l''ANAF dans le cadre de la validation, pas seulement un contrôle de format.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Validation pipeline';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Campos obligatorios clave', '[["Código de tipo de factura", "380 (estándar), 381 (nota de crédito)"], ["ID de proveedor / comprador", "CUI / CIF"], ["Códigos de tipo de IVA", "19% / 9% / 5%"], ["Códigos especiales", "Inversión del sujeto pasivo, factura simplificada"]]', 'Se requieren códigos de categoría fiscal específicos de Rumanía para los escenarios de inversión del sujeto pasivo y factura simplificada — los códigos genéricos de EN 16931 por sí solos no superarán la validación Schematron.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Key mandatory fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Wichtige Pflichtfelder', '[["Rechnungstypcode", "380 (Standard), 381 (Gutschrift)"], ["Lieferanten-/Käufer-ID", "CUI / CIF"], ["USt-Satz-Codes", "19 % / 9 % / 5 %"], ["Sondercodes", "Reverse Charge, vereinfachte Rechnung"]]', 'Für Reverse-Charge- und vereinfachte Rechnungsszenarien sind rumänienspezifische Steuerkategoriecodes erforderlich — allgemeine EN-16931-Codes allein bestehen die Schematron-Validierung nicht.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Key mandatory fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Champs obligatoires clés', '[["Code type de facture", "380 (standard), 381 (avoir)"], ["ID fournisseur / acheteur", "CUI / CIF"], ["Codes de taux de TVA", "19 % / 9 % / 5 %"], ["Codes spéciaux", "Autoliquidation, facture simplifiée"]]', 'Des codes de catégorie fiscale spécifiques à la Roumanie sont requis pour les scénarios d''autoliquidation et de facture simplifiée — les codes génériques EN 16931 seuls ne passeront pas la validation Schematron.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Key mandatory fields';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Archivo', '[["Período de conservación", "10 años"], ["Formato a conservar", "XML firmado original + respuesta de la ANAF"], ["Plazo de recuperación del comprador", "60 días desde el SPV"]]', 'Conserve tanto el XML que envió como la respuesta firmada/downloadId de la ANAF — el sello digital del gobierno (no su propia firma) es lo que hace que la factura sea legalmente válida.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Archivierung', '[["Aufbewahrungsfrist", "10 Jahre"], ["Aufzubewahrendes Format", "Original signiertes XML + ANAF-Antwort"], ["Abrufzeitraum für Käufer", "60 Tage ab SPV"]]', 'Bewahren Sie sowohl das eingereichte XML als auch die signierte Antwort/downloadId der ANAF auf — das digitale Siegel des Staates (nicht Ihre eigene Signatur) macht die Rechnung rechtlich gültig.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Archivage', '[["Durée de conservation", "10 ans"], ["Format à conserver", "XML original signé + réponse de l''ANAF"], ["Délai de récupération pour l''acheteur", "60 jours depuis le SPV"]]', 'Conservez à la fois le XML soumis et la réponse signée/downloadId de l''ANAF — c''est le sceau numérique de l''État (et non votre propre signature) qui rend la facture juridiquement valide.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'file_format' AND dct.title = 'Archiving';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Plataforma y API', '[["Plataforma", "SPV (Spațiul Privat Virtual)"], ["Host de la API REST", "efactura.mfinante.gov.ro"], ["Autenticación (humana)", "Certificado digital cualificado"], ["Autenticación (M2M)", "OAuth 2.0"]]', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Platform & API';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Plattform & API', '[["Plattform", "SPV (Spațiul Privat Virtual)"], ["REST-API-Host", "efactura.mfinante.gov.ro"], ["Authentifizierung (Mensch)", "Qualifiziertes digitales Zertifikat"], ["Authentifizierung (M2M)", "OAuth 2.0"]]', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Platform & API';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Plateforme et API', '[["Plateforme", "SPV (Spațiul Privat Virtual)"], ["Hôte de l''API REST", "efactura.mfinante.gov.ro"], ["Authentification (humaine)", "Certificat numérique qualifié"], ["Authentification (M2M)", "OAuth 2.0"]]', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Platform & API';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Flujo de compensación', '[["1. Envío", "XML cargado a la ANAF"], ["2. Validación", "Comprobaciones estructurales y semánticas"], ["3. Sellado", "Firma digital del Ministerio de Finanzas"], ["4. Referencia", "Se emite un downloadId único"]]', 'Realice un seguimiento del estado del envío a través de pendiente → validado → rechazado. Cree lógica de reintento/espera progresiva — la infraestructura de la ANAF tiene problemas de fiabilidad conocidos durante los períodos de mayor presentación.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Clearance workflow';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Clearing-Workflow', '[["1. Einreichung", "XML an ANAF hochgeladen"], ["2. Validierung", "Strukturelle und semantische Prüfungen"], ["3. Versiegelung", "Digitale Signatur des Finanzministeriums"], ["4. Referenz", "Eindeutige downloadId wird ausgestellt"]]', 'Verfolgen Sie den Einreichungsstatus über ausstehend → validiert → abgelehnt. Bauen Sie eine Wiederholungs-/Backoff-Logik ein — die Infrastruktur der ANAF hat in Spitzenzeiten bekannte Zuverlässigkeitsprobleme.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Clearance workflow';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Flux de contrôle', '[["1. Soumission", "XML téléversé vers l''ANAF"], ["2. Validation", "Contrôles structurels et sémantiques"], ["3. Scellement", "Signature numérique du ministère des Finances"], ["4. Référence", "Un downloadId unique est délivré"]]', 'Suivez le statut de la soumission entre en attente → validé → rejeté. Mettez en place une logique de nouvelle tentative/backoff — l''infrastructure de l''ANAF connaît des problèmes de fiabilité identifiés lors des périodes de pointe.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Clearance workflow';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Reglas de plazos', '[["Plazo de envío", "5 días naturales desde la emisión"], ["Plazo de descarga del comprador", "60 días"], ["Envío tardío", "Infracción de cumplimiento"]]', 'El plazo de 5 días comienza en el momento del devengo (hecho imponible), no en la fecha en que finalmente genera el XML — automatice el envío inmediatamente tras la emisión en lugar de procesarlo por lotes.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Timing rules';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Zeitregeln', '[["Übermittlungsfrist", "5 Kalendertage ab Ausstellung"], ["Download-Zeitraum für Käufer", "60 Tage"], ["Verspätete Einreichung", "Compliance-Verstoß"]]', 'Die 5-Tage-Frist beginnt mit dem Steuertatbestand (steuerauslösendes Ereignis), nicht mit dem Datum, an dem Sie das XML tatsächlich erzeugen — automatisieren Sie die Einreichung unmittelbar nach Ausstellung, statt sie zu bündeln.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Timing rules';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Règles de délais', '[["Délai de soumission", "5 jours calendaires à compter de l''émission"], ["Délai de téléchargement pour l''acheteur", "60 jours"], ["Soumission tardive", "Manquement de conformité"]]', 'Le délai de 5 jours démarre au fait générateur (événement taxable), et non à la date à laquelle vous générez enfin le XML — automatisez la soumission dès l''émission plutôt que de la traiter par lots.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Timing rules';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Obligaciones del comprador', '[["Registro", "También debe registrarse en el SPV"], ["Recuperación", "Consultar la API para facturas por CUI"], ["Verificación", "Confirmar la presencia de un sello válido del MF"]]', 'Los compradores no son receptores pasivos — se espera que recuperen activamente las facturas dirigidas a su CUI y pueden presentar una reclamación de cumplimiento si un proveedor no emite correctamente.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Buyer-side obligations';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichten des Käufers', '[["Registrierung", "Muss sich ebenfalls im SPV registrieren"], ["Abruf", "API nach Rechnungen anhand der CUI abfragen"], ["Überprüfung", "Vorhandensein eines gültigen MF-Siegels bestätigen"]]', 'Käufer sind keine passiven Empfänger — Sie müssen aktiv die an Ihre CUI adressierten Rechnungen abrufen und können eine Compliance-Beschwerde einreichen, wenn ein Lieferant nicht korrekt ausstellt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Buyer-side obligations';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Obligations de l''acheteur', '[["Inscription", "Doit également s''inscrire au SPV"], ["Récupération", "Interroger l''API pour les factures par CUI"], ["Vérification", "Confirmer la présence d''un sceau valide du ministère des Finances"]]', 'Les acheteurs ne sont pas des destinataires passifs — vous êtes censé récupérer activement les factures adressées à votre CUI et pouvez déposer une réclamation de conformité si un fournisseur n''émet pas correctement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'scope_transmission' AND dct.title = 'Buyer-side obligations';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📊 Reporte SAF-T', NULL, NULL, 'El Archivo Estándar de Auditoría para efectos fiscales (SAF-T) funciona junto con e-Factura, cubriendo datos contables más amplios más allá de las facturas individuales. Se implementó por separado, comenzando con los grandes contribuyentes en 2022 y extendiéndose progresivamente a empresas más pequeñas (Orden de la ANAF 1783/2021).' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '📊 SAF-T reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📊 SAF-T-Meldung', NULL, NULL, 'Die SAF-T-Meldung (Standard Audit File for Tax) läuft parallel zu e-Factura und deckt umfassendere Buchhaltungsdaten ab, die über einzelne Rechnungen hinausgehen. Sie wurde separat eingeführt, beginnend 2022 mit Großsteuerpflichtigen und schrittweise auf kleinere Unternehmen ausgeweitet (Anordnung der ANAF 1783/2021).' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '📊 SAF-T reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📊 Déclaration SAF-T', NULL, NULL, 'Le fichier d''audit standard à des fins fiscales (SAF-T) fonctionne parallèlement à e-Factura, couvrant des données comptables plus larges au-delà des factures individuelles. Il a été déployé séparément, en commençant par les grands contribuables en 2022 puis en s''étendant progressivement aux petites entreprises (arrêté de l''ANAF 1783/2021).' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '📊 SAF-T reporting';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🚚 RO e-Transport', NULL, NULL, 'Si transporta mercancías de alto riesgo dentro de Rumanía, las declaraciones logísticas deben hacer referencia cruzada al ID de compensación de e-Factura (downloadId) antes del envío. Trate e-Factura y e-Transport como un único flujo de cumplimiento conectado, no como dos sistemas separados.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '🚚 RO e-Transport';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🚚 RO e-Transport', NULL, NULL, 'Wenn Sie Waren mit hohem Risiko innerhalb Rumäniens transportieren, müssen die Logistikmeldungen vor dem Versand auf die e-Factura-Clearing-ID (downloadId) verweisen. Behandeln Sie e-Factura und e-Transport als einen zusammenhängenden Compliance-Workflow, nicht als zwei getrennte Systeme.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '🚚 RO e-Transport';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🚚 RO e-Transport', NULL, NULL, 'Si vous transportez des marchandises à haut risque à l''intérieur de la Roumanie, les déclarations logistiques doivent référencer l''identifiant de contrôle e-Factura (downloadId) avant l''expédition. Considérez e-Factura et e-Transport comme un seul flux de conformité lié, et non comme deux systèmes distincts.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '🚚 RO e-Transport';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '⚠️ Sanciones', NULL, NULL, 'Los envíos tardíos o faltantes generan multas de entre 1.000 y 5.000 RON para entidades pequeñas/medianas, y el incumplimiento puede sancionarse hasta con el 15% del valor de la factura — uno de los regímenes de aplicación más estrictos de la UE.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Penalties';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '⚠️ Sanktionen', NULL, NULL, 'Verspätete oder fehlende Einreichungen lösen Bußgelder von 1.000–5.000 RON für kleine/mittlere Unternehmen aus, und Nichteinhaltung kann mit bis zu 15 % des Rechnungswerts geahndet werden — eines der strengeren Durchsetzungssysteme in der EU.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Penalties';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '⚠️ Sanctions', NULL, NULL, 'Les soumissions tardives ou manquantes entraînent des amendes de 1 000 à 5 000 RON pour les petites/moyennes entités, et la non-conformité peut être sanctionnée jusqu''à 15 % de la valeur de la facture — l''un des régimes de sanction les plus stricts de l''UE.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Romania' AND dc.section = 'penalties_related' AND dct.title = '⚠️ Penalties';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Obtenga un certificado digital cualificado', 'Obtenga un certificado de firma electrónica cualificada de un proveedor rumano acreditado. Esta es la credencial que la ANAF utiliza para identificarle — prevea tiempo para esto, ya que la emisión del certificado no es inmediata.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Obtain a qualified digital certificate';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beschaffen Sie ein qualifiziertes digitales Zertifikat', 'Besorgen Sie sich ein qualifiziertes elektronisches Signaturzertifikat von einem akkreditierten rumänischen Anbieter. Dies ist der Berechtigungsnachweis, mit dem die ANAF Sie identifiziert — planen Sie hierfür Zeit ein, da die Zertifikatsausstellung nicht sofort erfolgt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Obtain a qualified digital certificate';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Obtenez un certificat numérique qualifié', 'Procurez-vous un certificat de signature électronique qualifiée auprès d''un prestataire roumain accrédité. C''est l''identifiant que l''ANAF utilise pour vous reconnaître — prévoyez du temps pour cela, car la délivrance du certificat n''est pas instantanée.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Obtain a qualified digital certificate';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Regístrese para acceder al SPV', 'Cree su cuenta de Spațiul Privat Virtual (Espacio Privado Virtual) — el portal seguro de contribuyentes de la ANAF — utilizando su certificado digital para autenticarse.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Register for SPV access';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie sich für den SPV-Zugang', 'Erstellen Sie Ihr Spațiul-Privat-Virtual-Konto (virtueller privater Raum) — das sichere Steuerpflichtigenportal der ANAF — und authentifizieren Sie sich dabei mit Ihrem digitalen Zertifikat.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Register for SPV access';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Inscrivez-vous pour accéder au SPV', 'Créez votre compte Spațiul Privat Virtual (espace privé virtuel) — le portail sécurisé des contribuables de l''ANAF — en vous authentifiant à l''aide de votre certificat numérique.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Register for SPV access';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Presente el Formulario 084', 'Presente el Formulario 084 para activar formalmente el acceso a RO e-Factura para su CUI/CIF. Este es el paso de registro específico que habilita la capacidad de facturación electrónica dentro del SPV.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Submit Form 084';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Reichen Sie Formular 084 ein', 'Reichen Sie Formular 084 ein, um den Zugang zu RO e-Factura für Ihre CUI/CIF formell zu aktivieren. Dies ist der konkrete Registrierungsschritt, der die E-Invoicing-Funktion innerhalb des SPV freischaltet.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Submit Form 084';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Soumettez le formulaire 084', 'Déposez le formulaire 084 pour activer formellement l''accès à RO e-Factura pour votre CUI/CIF. C''est l''étape d''inscription spécifique qui active la fonction de facturation électronique au sein du SPV.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Submit Form 084';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure la delegación de certificado (si utiliza un proveedor de servicios)', 'Si una plataforma externa o un contable presenta las facturas en su nombre, delégueles la autoridad del certificado por entidad. Esta suele ser la parte más complicada de la integración — las delegaciones deben configurarse individualmente y los certificados caducan, así que haga un seguimiento de las fechas de renovación.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Set up certificate delegation (if using a service provider)';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine Zertifikatsdelegation ein (bei Nutzung eines Dienstleisters)', 'Wenn eine Drittplattform oder ein Steuerberater in Ihrem Namen einreicht, delegieren Sie diesen die Zertifikatsberechtigung pro Einheit. Dies ist üblicherweise der kniffligste Teil der Integration — Delegationen müssen einzeln eingerichtet werden, und Zertifikate laufen ab, verfolgen Sie also die Verlängerungstermine.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Set up certificate delegation (if using a service provider)';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Configurez la délégation de certificat (si vous passez par un prestataire)', 'Si une plateforme tierce ou un comptable soumet en votre nom, déléguez-lui l''autorité de certificat par entité. C''est généralement la partie la plus délicate de l''intégration — les délégations doivent être configurées individuellement et les certificats expirent, alors suivez les dates de renouvellement.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Set up certificate delegation (if using a service provider)';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Conecte su ERP o software de facturación', 'Intégrese a través de la API REST de la ANAF utilizando OAuth 2.0 para el envío máquina a máquina, o utilice directamente la interfaz web del SPV para volúmenes más bajos. Realice pruebas exhaustivas — la validación RO_CIUS es estricta, y las referencias de CUI/CIF no válidas provocan un rechazo inmediato.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Connect your ERP or invoicing software';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verbinden Sie Ihr ERP oder Ihre Rechnungssoftware', 'Integrieren Sie über die REST-API der ANAF mit OAuth 2.0 für die Maschine-zu-Maschine-Einreichung, oder nutzen Sie für geringere Volumina direkt die Weboberfläche des SPV. Testen Sie gründlich — die RO_CIUS-Validierung ist streng, und ungültige CUI/CIF-Referenzen führen zur sofortigen Ablehnung.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Connect your ERP or invoicing software';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Connectez votre ERP ou votre logiciel de facturation', 'Intégrez via l''API REST de l''ANAF avec OAuth 2.0 pour la soumission de machine à machine, ou utilisez directement l''interface web du SPV pour de plus faibles volumes. Testez minutieusement — la validation RO_CIUS est stricte, et des références CUI/CIF invalides entraînent un rejet immédiat.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Connect your ERP or invoicing software';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Incorpore la supervisión en su flujo de trabajo', 'Consulte el estado de compensación (pendiente/validado/rechazado), realice un seguimiento del plazo de 5 días por factura, y mantenga una lógica de reintento/espera progresiva para que las facturas se envíen exactamente una vez incluso si el endpoint de la ANAF no está disponible temporalmente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Build monitoring into your pipeline';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Integrieren Sie Überwachung in Ihre Pipeline', 'Fragen Sie den Clearing-Status ab (ausstehend/validiert/abgelehnt), verfolgen Sie die 5-Tage-Frist pro Rechnung und pflegen Sie eine Wiederholungs-/Backoff-Logik, damit Rechnungen genau einmal übermittelt werden, selbst wenn der Endpunkt der ANAF vorübergehend nicht verfügbar ist.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Build monitoring into your pipeline';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Intégrez une surveillance dans votre pipeline', 'Interrogez le statut de contrôle (en attente/validé/rejeté), suivez le délai de 5 jours par facture, et maintenez une logique de nouvelle tentative/backoff afin que les factures soient soumises exactement une fois, même si le point de terminaison de l''ANAF est temporairement indisponible.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Romania' AND dst.title = 'Build monitoring into your pipeline';

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'es', 'ANAF / Ministerio de Finanzas — e-Factura' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Romania';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'de', 'ANAF / Finanzministerium — e-Factura' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Romania';
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT dp.id, 'fr', 'ANAF / Ministère des Finances — e-Factura' FROM deep_dive_portals dp JOIN countries c ON c.id = dp.country_id WHERE c.name_en = 'Romania';
